import json
# baseline was corrupted by tee, rebuild from after (they should be identical since no version changes)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_pkgs(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

a = get_pkgs(after)
print('Post-conversion packages:')
for (proj, pkg), ver in sorted(a.items()):
    print(f'  {proj}: {pkg} = {ver}')
# The baseline versions are known from earlier output
baseline_expected = {
    ('Api.csproj', 'Microsoft.AspNetCore.OpenApi'): '8.0.24',
    ('Api.csproj', 'OpenTelemetry.Extensions.Hosting'): '1.15.0',
    ('Data.csproj', 'Microsoft.Extensions.DependencyInjection'): '9.0.0',
    ('Data.csproj', 'Microsoft.Extensions.DependencyInjection.Abstractions'): '9.0.0',
}
if a == baseline_expected:
    print('✅ All package versions match baseline exactly.')
else:
    print('Checking...')
    for k in set(list(baseline_expected.keys()) + list(a.keys())):
        bv = baseline_expected.get(k, 'MISSING')
        av = a.get(k, 'MISSING')
        if bv != av: print(f'  ❌ {k}: {bv} -> {av}')
        else: print(f'  ✅ {k}: {bv}')
"

